import type { MigrationBuilder } from "node-pg-migrate";
import { readFile } from "node:fs/promises";
/** Operational role provisioning only. Business schema migrations remain
 * QueryInterface/Umzug; every statement here is generated by node-pg-migrate's
 * structured grant/revoke API, never by hand-written SQL.
 *
 * 001 granted `settings` SELECT only (identity fingerprint reads). 005 adds the
 * `layout` settings row, which the runtime role writes with an upsert, plus the
 * explicit re-grant of the `students.experimentGroup` UPDATE path introduced by
 * the 005-experiment-group schema migration. */
export async function up(pgm: MigrationBuilder) {
  const file = process.env.RUNTIME_DATABASE_URL_FILE;
  if (!file) throw new Error("RUNTIME_DATABASE_URL_FILE_REQUIRED");
  const role = decodeURIComponent(
    new URL((await readFile(file, "utf8")).trim()).username,
  );
  if (!/^[a-z][a-z0-9_]{2,62}$/.test(role))
    throw new Error("RUNTIME_ROLE_INVALID");
  // `layout` lives in the settings table: SELECT was granted in 001, the row
  // upsert of PUT /api/v1/layout needs INSERT and UPDATE as well.
  pgm.grantOnTables({
    tables: ["settings"],
    roles: role,
    privileges: ["SELECT", "INSERT", "UPDATE"],
  });
  // students UPDATE was granted in 001 (profile refresh); re-grant explicitly so
  // the column-level dependency of the experiment toggle is an auditable step.
  pgm.grantOnTables({
    tables: ["students"],
    roles: role,
    privileges: ["SELECT", "INSERT", "UPDATE"],
  });
}
